"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Cygnus Expanse Gambit', 'author': 'Signature original', 'genre': 'First Contact', 'chapters': [{'n': 1, 'title': 'Launch', 'text': "They grappled a coded starlog with the cargo arm as the first raider shells crossed their bow. the android Echo whooped as the airlock sealed. Whatever a coded starlog was, it was theirs now — and the Hollow Fleet knew it.\n\nthe android Echo ran the numbers with grease on their hands and worry in their eyes. 'the Hollow Fleet has three ships in the drift,' they said. 'If we burn hard, we can make it. If we burn hard, everyone will see us.'\n\nIn the hold, under work lights, Pilot Vera Quill studied a coded starlog. It pulsed faintly, like a heart. 'light against the void,' Pilot Vera Quill murmured. 'Let's find out what you are.'"}, {'n': 2, 'title': 'The Chart Unfolds', 'text': "The crew voted — that was Pilot Vera Quill's rule, always a vote before a suicide run. Every hand went up. the android Echo grinned. 'We didn't sign on for safe,' they said.\n\n'It's a map,' breathed Pilot Vera Quill, 'and a warning.' The route it drew cut through the worst of the drift: plasma storms, minefields, and the patrol lanes of the Hollow Fleet.\n\nthe android Echo cracked a coded starlog's casing with a spanner and a prayer. Inside: coordinates, a starlog, a voice saying one word over and over — the name of the Cygnus Expanse."}, {'n': 3, 'title': 'Storm Season', 'text': "A mine took their port array. The deck went dark, then red. the android Echo was already moving, cable in teeth, splicing by feel. 'Talk to me,' Pilot Vera Quill said, and the android Echo talked — numbers, jokes, anything to keep the fear small.\n\nThrough the fire they saw it: the Hollow Fleet's flagship, waiting in the storm's eye like a spider. 'They knew the route,' Pilot Vera Quill said. 'Someone sold the starlog.' The betrayal sat cold in their stomach.\n\nThe battle was short and ugly. Pilot Vera Quill used the storm itself as a weapon, luring the flagship into a plasma surge that stripped its shields. They escaped in the glare, hull scorched, crew cheering raggedly."}, {'n': 4, 'title': "The Traitor's Price", 'text': "Pilot Vera Quill let them live, confined to quarters. 'the Hollow Fleet trades in hostages,' Pilot Vera Quill told the crew. 'We trade in something better.' It was a gamble; the crew's eyes said they knew it.\n\nThe traitor showed themselves at the third waypoint: the signal officer, paid in promises by the Hollow Fleet. They seized a coded starlog and ran for the escape pod with the Hollow Fleet's ships closing in.\n\nPilot Vera Quill laughed for the first time in days. 'All this way,' they said, 'and we were carrying the lock, not the treasure.' the android Echo was already calculating the wake-up sequence."}, {'n': 5, 'title': 'The Grid Awakens', 'text': "the android Echo fed a coded starlog into the ancient console. For a heartbeat nothing happened — then the sky caught fire, a lattice of light wrapping the Cygnus Expanse like a held breath. the Hollow Fleet's vanguard shattered against it like waves on rock.\n\nThe duel was legend before it ended: two ships in the fire-light, neither yielding, until Pilot Vera Quill did the impossible — dove through the grid's own gate, which a coded starlog held open, and watched the Hollow Fleet break against the shield they could not see.\n\nThey reached the Cygnus Expanse with the Hollow Fleet's whole fleet behind them, a wall of iron against the stars. Pilot Vera Quill broadcast on all bands: 'People of the Cygnus Expanse, wake the grid. Now.'"}, {'n': 6, 'title': 'Home Signal', 'text': "The traitor's family was found and freed; the traitor wept and was forgiven, and signed on again — this time for real. Pilot Vera Quill's rule about second chances held, barely, and gloriously.\n\nThey landed at the Cygnus Expanse to crowds and bells. The old voice from the starlog had belonged to the grid's last keeper, dead a hundred years; a coded starlog was their final message. Pilot Vera Quill laid it in the memorial with honors.\n\nthe android Echo was offered an admiralty and laughed in the committee's face. 'I have a ship,' they said. It was the highest compliment the crew had ever heard."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

